const data = global.get("parat_bridge");
let messages = msg.payload;

if (!Array.isArray(messages)) messages = [messages];

messages.forEach(entry => {
    // Determine which system this message should be sent TO
    if (!entry.target) {
        entry.target = (entry.client === "rayvn") ? "wasos" : "rayvn";
    }

    // Ensure every entry is linked to a connection
    if (!entry.connection_id && msg.connection) {
        entry.connection_id = msg.connection.id;
    }

    // Add queue metadata for retry tracking
    entry.retryCount = entry.retryCount || 0;
    entry.createdAt = entry.createdAt || new Date().toISOString();
    entry.lastError = entry.lastError || null;

    // Find the owning connection and add to its queue
    const connection = data.connections.find(c => c.id === entry.connection_id);

    if (connection) {
        connection.queue.push(entry);
    } else {
        node.warn("No connection found for entry with connection_id: " + entry.connection_id);
    }
});

global.set("parat_bridge", data);

// When receiving a split batch, only trigger send after the last part
if (msg.parts && msg.parts.index !== msg.parts.count - 1) {
    return null;
}

return msg;

const data = global.get("parat_bridge");
const connectionId = msg.connection ? msg.connection.id : null;

let dequeuedEntry = null;

if (connectionId) {
    const connection = data.connections.find(c => c.id === connectionId);

    if (connection) {
        const entryIndex = connection.queue.findIndex(e => e.id === msg.msg_id);

        if (entryIndex !== -1) {
            dequeuedEntry = connection.queue.splice(entryIndex, 1)[0];
            global.set("parat_bridge", data);
        }
    }
}

msg.payload = dequeuedEntry ? [dequeuedEntry] : [];
return msg;

const data = global.get("parat_bridge");

// Collect all queued entries across active connections into a flat list
// Each item carries a reference to its owning connection
const allQueuedEntries = [];

data.connections.forEach(connection => {
    if (!connection.active) return;

    connection.queue.forEach(entry => {
        allQueuedEntries.push({ entry, connection });
    });
});

if (allQueuedEntries.length === 0) {
    context.set("sending", false);
    return null;
}

// Release the sending lock when we get a response back
if (msg.topic === "response") {
    context.set("sending", false);
}

// Only send one message at a time — wait for response before next
if (context.get("sending")) return null;

// Manage temporarily blocked connections (after max retries)
const blockedConnections = context.get("blocked_connections") || {};
const now = Date.now();
const BLOCK_DURATION_MS = 30000; // 30 seconds

// Clean up expired blocks
for (const connectionId in blockedConnections) {
    if (now - blockedConnections[connectionId] > BLOCK_DURATION_MS) {
        delete blockedConnections[connectionId];
    }
}
context.set("blocked_connections", blockedConnections);

// Find the first entry whose connection is not currently blocked
const nextToSend = allQueuedEntries.find(
    item => !blockedConnections[item.connection.id]
);

if (!nextToSend) {
    // All queued entries belong to blocked connections — wait
    context.set("sending", false);
    return null;
}

context.set("sending", true);
msg.msg_id = nextToSend.entry.id;
msg.payload = [nextToSend.entry];
msg.connection = nextToSend.connection;

return msg;

const data = global.get("parat_bridge");

const RETRY_LIMIT = context.get("retry_limit") || 5;
let currentMessageId = context.get("current_id");
let attemptCount = context.get("retries") || 0;

const connectionId = msg.connection ? msg.connection.id : null;

// --- Helper: increment retry count on the queued entry ---
function recordRetryAttempt() {
    if (!connectionId) return;

    const connection = data.connections.find(c => c.id === connectionId);
    if (!connection) return;

    const entry = connection.queue.find(e => e.id === msg.msg_id);
    if (!entry) return;

    entry.retryCount = (entry.retryCount || 0) + 1;
    entry.lastError = "HTTP " + (msg.statusCode || "unknown");
    global.set("parat_bridge", data);
}

// --- New message or same message retrying? ---
if (!currentMessageId || currentMessageId !== msg.msg_id) {
    // First failure for this message — start tracking
    context.set("current_id", msg.msg_id);
    context.set("retries", 1);
    recordRetryAttempt();
    return [null, msg, null]; // Output 1: retry
}

attemptCount = context.get("retries");

if (attemptCount < RETRY_LIMIT) {
    // Still have retries left — try again
    context.set("retries", attemptCount + 1);
    recordRetryAttempt();
    return [null, msg, null]; // Output 1: retry
}

// --- Max retries exhausted — give up on this message ---

// Remove from connection's queue
let failedEntry = null;
if (connectionId) {
    const connection = data.connections.find(c => c.id === connectionId);
    if (connection) {
        const entryIndex = connection.queue.findIndex(e => e.id === msg.msg_id);
        if (entryIndex !== -1) {
            failedEntry = connection.queue.splice(entryIndex, 1)[0];
            global.set("parat_bridge", data);
        }
    }
}

// Temporarily block this connection so other connections can proceed
if (failedEntry) {
    const blockedConnections = context.get("blocked_connections") || {};
    blockedConnections[failedEntry.connection_id] = Date.now();
    context.set("blocked_connections", blockedConnections);
}

// Reset retry state for the next message
context.set("retries", 0);
context.set("current_id", "");

// Check: is this a system notification? If so, do NOT trigger another notification (loop prevention)
const isSystemMessage = failedEntry && failedEntry.client === "parat-bridge";

msg.failed_messages = failedEntry ? [failedEntry] : [];
msg.payload = failedEntry ? [failedEntry] : [];
msg.status = "failed";

if (isSystemMessage) {
    // System message failed — log it, but don't try to notify (would cause infinite loop)
    return [null, null, msg]; // Output 2: master_log only
} else {
    // User message failed — notify sender AND log the failure
    return [msg, null, msg]; // Output 0: System handling + Output 2: master_log
}

